// decoded lazily per title: -> [{ t, mask, level }]
const _decoded = {};
export function lightCues(title) {
  if (_decoded[title]) return _decoded[title];
  const raw = LIGHT_CUES[title];
  if (!raw) return (_decoded[title] = []);
  const out = [];
  const parts = raw.split(",");
  for (let i = 0; i < parts.length; i++) {
    const s = parts[i];
    out.push({
      t: parseInt(s.slice(0, -3), 36) * 0.02,
      mask: parseInt(s.slice(-3, -1), 36),
      level: parseInt(s.slice(-1), 10),
    });
  }
  return (_decoded[title] = out);
}
